#include <iostream>
#include <vector>
#include <string>
using namespace std;

int main() {
    long long n;
    cin >> n;
    vector<long long> a(n);
    for (int i = 0; i < n; i++) cin >> a[i];
    long long x;
    cin >> x;

    int count = 0;
    for (long long v : a) {
        if (v == x) {
            count++;
        }
    }
    cout << count << endl;

    return 0;
}

code.java:
import java.util.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        long[] a = new long[(int) n];
        for (int i = 0; i < a.length; i++) a[i] = sc.nextLong();
        long x = sc.nextLong();

        int count = 0;
        for (long v : a) {
            if (v == x) {
                count++;
            }
        }
        System.out.println(count);
    }
}
